TEST_CASE(pntedg_golden)
{
    CHECK(sizeof kGold / sizeof kGold[0] == 42);
    for (const Gold& g : kGold) {
        double x[12], p[3];
        for (int i = 0; i < 12; ++i) x[i] = std::bit_cast<double>(g.x[i]);
        for (int i = 0; i < 3; ++i) p[i] = std::bit_cast<double>(g.p[i]);
        double xi = -7.0, eta = -7.0, q[3] = {-9.0, -9.0, -9.0}, d = -5.0;
        def::rt::geoutl::fun_1404d41f8(x, p, &xi, &eta, q, &d);
        CHECK_BITS(xi, std::bit_cast<double>(g.out[0]));
        CHECK_BITS(eta, std::bit_cast<double>(g.out[1]));
        CHECK_BITS(q[0], std::bit_cast<double>(g.out[2]));
        CHECK_BITS(q[1], std::bit_cast<double>(g.out[3]));
        CHECK_BITS(q[2], std::bit_cast<double>(g.out[4]));
        CHECK_BITS(d, std::bit_cast<double>(g.out[5]));
    }
}

int main() { return testkit::run_all(); }
